	__models__GongNoteShape__00000006_.Name = `07. RadioCommunicationChannel & PilotControlledLighting-Note07RadioComm`
	__models__GongNoteShape__00000006_.Identifier = `ref_models.Note07RadioComm`
	__models__GongNoteShape__00000006_.Body = `07. RadioCommunicationChannel & PilotControlledLighting Story

[models.RadioCommunicationChannelTimeSliceType] defines VHF/UHF/HF frequencies, emission class, [models.CallsignDetailType],
[models.CircleSectorType] coverage, and [models.RadioCommunicationOperationalStatusType], while [models.PilotControlledLightingTimeSliceType] models radio-activated lighting.
`
	__models__GongNoteShape__00000006_.BodyHTML = `<p>07. RadioCommunicationChannel &amp; PilotControlledLighting Story
<p><a href="/models#RadioCommunicationChannelTimeSliceType">models.RadioCommunicationChannelTimeSliceType</a> defines VHF/UHF/HF frequencies, emission class, <a href="/models#CallsignDetailType">models.CallsignDetailType</a>,
<a href="/models#CircleSectorType">models.CircleSectorType</a> coverage, and <a href="/models#RadioCommunicationOperationalStatusType">models.RadioCommunicationOperationalStatusType</a>, while <a href="/models#PilotControlledLightingTimeSliceType">models.PilotControlledLightingTimeSliceType</a> models radio-activated lighting.
`
